import { useMemo, useState } from 'react';
import {
  Badge,
  Button,
  Card,
  Chip,
  CircularProgress,
  EmptyState,
  Pagination,
  Stack,
  Text,
} from '@jinx-ui/react';

// Состав и пропсы компонентов @jinx-ui/react взяты по предположению — сверьте с актуальным API пакета.

type ProjectStatus = 'active' | 'paused' | 'exceeded' | 'archived';

export type Project = {
  id: string;
  name: string;
  used: number;
  quota: number;
  status: ProjectStatus;
};

type ProjectSpendPanelProps = {
  projects: Project[];
};

const PAGE_SIZE = 5;

const STATUS_ORDER: ProjectStatus[] = ['active', 'paused', 'exceeded', 'archived'];

const STATUS_META: Record<
  ProjectStatus,
  { label: string; tone: 'success' | 'warning' | 'danger' | 'neutral' }
> = {
  active: { label: 'Активен', tone: 'success' },
  paused: { label: 'На паузе', tone: 'warning' },
  exceeded: { label: 'Превышен', tone: 'danger' },
  archived: { label: 'Архив', tone: 'neutral' },
};

function toPercent(used: number, quota: number): number {
  if (quota <= 0) return 0;
  return Math.min(100, Math.round((used / quota) * 100));
}

export default function ProjectSpendPanel({ projects }: ProjectSpendPanelProps) {
  const [selected, setSelected] = useState<ProjectStatus[]>([]);
  const [page, setPage] = useState(1);

  const filtered = useMemo(
    () =>
      selected.length === 0
        ? projects
        : projects.filter((project) => selected.includes(project.status)),
    [projects, selected],
  );

  const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, totalPages);
  const rows = filtered.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  const toggleStatus = (status: ProjectStatus) => {
    setSelected((prev) =>
      prev.includes(status) ? prev.filter((item) => item !== status) : [...prev, status],
    );
    setPage(1);
  };

  const resetFilters = () => {
    setSelected([]);
    setPage(1);
  };

  return (
    <Card>
      <Stack direction="column" style={{ gap: 'var(--jx-space-4)' }}>
        <Stack
          direction="row"
          wrap
          align="center"
          role="group"
          aria-label="Фильтр по статусу"
          style={{ gap: 'var(--jx-space-2)' }}
        >
          {STATUS_ORDER.map((status) => {
            const isSelected = selected.includes(status);
            return (
              <Chip
                key={status}
                selected={isSelected}
                aria-pressed={isSelected}
                onClick={() => toggleStatus(status)}
                onRemove={isSelected ? () => toggleStatus(status) : undefined}
              >
                {STATUS_META[status].label}
              </Chip>
            );
          })}
          {selected.length > 0 && (
            <Button variant="ghost" size="sm" onClick={resetFilters}>
              Сбросить
            </Button>
          )}
        </Stack>

        {rows.length === 0 ? (
          <EmptyState
            title="Проектов не найдено"
            description="По выбранным статусам нет ни одного проекта."
            action={<Button onClick={resetFilters}>Сбросить фильтры</Button>}
          />
        ) : (
          <Stack direction="column" style={{ gap: 'var(--jx-space-2)' }}>
            {rows.map((project) => {
              const percent = toPercent(project.used, project.quota);
              const meta = STATUS_META[project.status];
              return (
                <Stack
                  key={project.id}
                  direction="row"
                  align="center"
                  style={{ gap: 'var(--jx-space-3)', padding: 'var(--jx-space-2) 0' }}
                >
                  <Text style={{ flex: '1 1 auto' }}>{project.name}</Text>
                  <Stack direction="row" align="center" style={{ gap: 'var(--jx-space-2)' }}>
                    <CircularProgress
                      value={percent}
                      size="sm"
                      aria-label={`Квота проекта ${project.name} использована на ${percent}%`}
                    />
                    <Text variant="caption">{percent}%</Text>
                  </Stack>
                  <Badge tone={meta.tone}>{meta.label}</Badge>
                </Stack>
              );
            })}
          </Stack>
        )}

        {rows.length > 0 && totalPages > 1 && (
          <Pagination page={currentPage} pageCount={totalPages} onPageChange={setPage} />
        )}
      </Stack>
    </Card>
  );
}

